def find_overlapping_section(N, M, first_map, second_map):
    for i in range(N - M + 1):
        for j in range(M - M + 1):
            if all(first_map[i + x][j + y] == second_map[x][y] for x in range(M) for y  in range(M)):
                return (i + 1, j + 1)

